import{_ as a,o as t,c as n,ag as i}from"./chunks/framework.BGkQCay2.js";const h=JSON.parse('{"title":"Runtime Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/runtime-architecture.md","filePath":"architecture/runtime-architecture.md"}'),r={name:"architecture/runtime-architecture.md"};function s(o,e,d,c,l,p){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="runtime-architecture" tabindex="-1">Runtime Architecture <a class="header-anchor" href="#runtime-architecture" aria-label="Permalink to &quot;Runtime Architecture&quot;">​</a></h1><p>VexArch is the target-routed runtime implemented in Vex under <code>lib/runtime/VexArch</code>. It provides allocation, ownership support, async scheduling, channels, I/O, networking integration, panic paths, and platform ABI adapters without making libc an implicit language dependency.</p><p>The separately packaged <code>vex-runtime-core</code> Rust artifact is a hosted compatibility option. It is not folded into the freestanding VexArch object, bitcode, or archive.</p><h2 id="runtime-layer-map" tabindex="-1">Runtime Layer Map <a class="header-anchor" href="#runtime-layer-map" aria-label="Permalink to &quot;Runtime Layer Map&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+------------------------------------------------------+</span></span>
<span class="line"><span>| Vex application and lib/std public APIs              |</span></span>
<span class="line"><span>+------------------------------------------------------+</span></span>
<span class="line"><span>                         |</span></span>
<span class="line"><span>                         v</span></span>
<span class="line"><span>+------------------------------------------------------+</span></span>
<span class="line"><span>| Compiler HIR/ABI lowering and generated code         |</span></span>
<span class="line"><span>+------------------------------------------------------+</span></span>
<span class="line"><span>                         |</span></span>
<span class="line"><span>                         v</span></span>
<span class="line"><span>+------------------------------------------------------+</span></span>
<span class="line"><span>| VexArch                                               |</span></span>
<span class="line"><span>| mem | async | channel | io | unwind | platform glue  |</span></span>
<span class="line"><span>+------------------------------------------------------+</span></span>
<span class="line"><span>             |                          |</span></span>
<span class="line"><span>             v                          v</span></span>
<span class="line"><span>+---------------------------+  +------------------------+</span></span>
<span class="line"><span>| Explicit OS system ABI    |  | Manifest-owned native |</span></span>
<span class="line"><span>| SYSTEM / selected LIBC    |  | NATIVE feature        |</span></span>
<span class="line"><span>+---------------------------+  +------------------------+</span></span></code></pre></div><p>There is no universal <code>extern &quot;C&quot;</code> import bucket. Every imported symbol states its owner:</p><table tabindex="0"><thead><tr><th>Provider</th><th>Meaning</th></tr></thead><tbody><tr><td><code>extern &quot;LIBC&quot;</code></td><td>An intentional hosted C-library dependency</td></tr><tr><td><code>extern &quot;SYSTEM&quot; from &quot;library&quot;</code></td><td>A named operating-system DLL, dylib, or framework</td></tr><tr><td><code>extern &quot;VEX&quot;</code></td><td>Compiler/runtime-owned ABI; reserved for VexArch, prelude, and standard-library internals</td></tr><tr><td><code>extern &quot;NATIVE&quot; from &quot;feature&quot;</code></td><td>A package native feature whose artifacts are declared in <code>vex.json</code></td></tr></tbody></table><p><code>export &quot;C&quot; fn</code> is different: it defines an unmangled outbound C-ABI symbol. It does not select an import provider or add a library dependency.</p><p>See the <a href="/docs/guide/ffi">FFI guide</a> for the complete provider contract.</p><h2 id="target-routed-sources" tabindex="-1">Target-Routed Sources <a class="header-anchor" href="#target-routed-sources" aria-label="Permalink to &quot;Target-Routed Sources&quot;">​</a></h2><p>Vex source files can select an OS and architecture directly. For an import of <code>native.vx</code>, resolution uses the first file that exists:</p><ol><li><code>native.&lt;os&gt;.&lt;arch&gt;.vx</code></li><li><code>native.&lt;os&gt;.vx</code></li><li><code>native.&lt;arch&gt;.vx</code></li><li><code>native.vx</code></li></ol><p>The same rule applies to <code>.vxc</code>. Source routing uses OS/architecture names; package native artifacts use exact target triples. These are intentionally separate mechanisms.</p><h2 id="memory-and-freestanding-boundary" tabindex="-1">Memory and Freestanding Boundary <a class="header-anchor" href="#memory-and-freestanding-boundary" aria-label="Permalink to &quot;Memory and Freestanding Boundary&quot;">​</a></h2><p>The active memory implementation lives under <code>VexArch/src/mem</code>:</p><ul><li><code>arena.vx</code> owns arena state, region tokens, and runtime state;</li><li><code>alloc.vx</code> owns slab, heap, realloc, and compatibility allocation entry points;</li><li><code>vumm.vx</code> implements Vex Unified Memory Model routing;</li><li><code>raw_pages.*.vx</code> and <code>compat.*.vx</code> provide target-specific page, thread, and process primitives.</li></ul><p>VexArch does not require a hosted <code>malloc/free</code> allocator. Target code may call explicit system APIs, direct kernel interfaces, or selected hosted facilities, but such dependencies remain visible through the provider and final link plan. A freestanding link rejects activated <code>LIBC</code> requirements.</p><p>Prelude types such as <code>Box</code>, <code>Vec</code>, <code>string</code>, and <code>Mem</code> use the reserved VEX ABI internally. Application code consumes their public APIs instead of declaring raw allocator symbols.</p><h2 id="async-runtime-and-channels" tabindex="-1">Async Runtime and Channels <a class="header-anchor" href="#async-runtime-and-channels" aria-label="Permalink to &quot;Async Runtime and Channels&quot;">​</a></h2><p>The scheduler and async state machine support live under <code>VexArch/src/async</code>:</p><ul><li><code>async.vx</code> owns worker/task scheduling and lifecycle;</li><li><code>channel.vx</code> implements channel state and waiter coordination;</li><li><code>timer_wheel.vx</code> tracks timed wakeups;</li><li><code>poller.&lt;target&gt;.vx</code> integrates the target event mechanism.</li></ul><p>Target files select the appropriate implementation at compile time. Runtime modules import concrete Vex implementations directly where possible. A small number of reserved VEX ABI edges remain where two core runtime modules form a deliberate dependency cycle or where a native bootstrap shim supplies the symbol.</p><h2 id="i-o-and-networking" tabindex="-1">I/O and Networking <a class="header-anchor" href="#i-o-and-networking" aria-label="Permalink to &quot;I/O and Networking&quot;">​</a></h2><p>VexArch owns stream state and exposes runtime I/O entry points. Target-specific files such as <code>io/native.macos.vx</code>, <code>io/native.linux.vx</code>, and <code>io/native.windows.vx</code> bind to the relevant system surface without exposing C <code>FILE</code> layout as Vex ABI.</p><p><code>lib/std/io</code>, <code>lib/std/fs</code>, and <code>lib/std/net</code> build public, typed APIs over this boundary. Their low-level target files use explicit <code>SYSTEM</code>, <code>LIBC</code>, <code>VEX</code>, or <code>NATIVE</code> declarations according to the actual symbol owner. Optional native codecs, database drivers, or TLS implementations are package features rather than hidden global linker inputs.</p><h2 id="extern-activation-and-linking" tabindex="-1">Extern Activation and Linking <a class="header-anchor" href="#extern-activation-and-linking" aria-label="Permalink to &quot;Extern Activation and Linking&quot;">​</a></h2><p>Parsing an extern declaration alone has no link effect. Codegen records the providers required by emitted uses, and the CLI constructs a deterministic native link plan from those activated requirements.</p><p>Important failures are reported before native linking:</p><ul><li>an activated <code>LIBC</code> provider is rejected in freestanding mode;</li><li>an unresolved <code>VEX</code> provider is rejected when <code>--no-runtime</code> is selected;</li><li>a <code>NATIVE</code> feature must resolve to artifacts owned by the package manifest;</li><li>system libraries are deduplicated deterministically.</li></ul><p>Provider requirements are preserved beside warm prelude cache entries, so a warm compile cannot silently lose an FFI dependency.</p><h2 id="runtime-semantic-image-and-fusion" tabindex="-1">Runtime Semantic Image and Fusion <a class="header-anchor" href="#runtime-semantic-image-and-fusion" aria-label="Permalink to &quot;Runtime Semantic Image and Fusion&quot;">​</a></h2><p>VexArch is not shipped or linked as a separate LLVM bitcode, object, static archive, or shared library. Cargo validates the VexArch package and embeds a deterministic, versioned Vex Runtime Image (VRI) in the compiler. The image contains lossless pre-parsed syntax, stable package/source identities, provenance and target selectors.</p><p>For each user compilation the compiler rehydrates the selected VRI sources without invoking the parser. User code, the prelude and VexArch then enter one semantic graph. Exact <code>DefId</code> reachability, monomorphization and callback address-taking decide which runtime bodies are materialized in the same backend module as user code. This keeps cross-boundary inlining and eliminates unused runtime code before backend DCE.</p><p>Architecture-specific assembly is allowed only for operations that cannot be expressed in Vex. Cargo assembles this tiny target pack once and embeds it in the compiler; the CLI materializes the content-addressed object only because native linkers require a filesystem input. It carries no Vex semantics.</p><h2 id="safety-rules" tabindex="-1">Safety Rules <a class="header-anchor" href="#safety-rules" aria-label="Permalink to &quot;Safety Rules&quot;">​</a></h2><ul><li>Foreign calls require an audited <code>unsafe</code> boundary.</li><li>A concrete local definition or explicit import owns its name over an ambient prelude extern declaration.</li><li>Raw VEX ABI declarations are runtime/standard-library internals, not the application-facing API.</li><li>Provider choice describes ownership; it is not inferred from a filename or platform convention.</li><li>Outbound <code>export &quot;C&quot; fn</code> definitions must expose explicitly ABI-safe types.</li></ul><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="/docs/guide/ffi">FFI</a> -- provider syntax and link behavior</li><li><a href="/docs/guide/ffi-deep-dive">FFI Deep Dive</a> -- ownership and ABI design</li><li><a href="/docs/guide/freestanding">Freestanding Vex</a> -- hosted and freestanding boundaries</li><li><a href="/docs/guide/memory/vumm">VUMM</a> -- Vex Unified Memory Model</li><li><a href="/docs/guide/concurrency/deep-dive">Concurrency Deep Dive</a> -- scheduler behavior</li></ul>`,38)])])}const m=a(r,[["render",s]]);export{h as __pageData,m as default};
